"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  type ChartStatus,
  ChartDataTable,
  ChartState,
  type BookLevel,
  DOWN,
  EASE,
  Keyframes,
  type OrderBook,
  SURFACE,
  UP,
  formatAxisPrice,
  formatMoney,
  formatSpread,
  generateOrderBook,
  niceTicks,
  useElementWidth,
  usePrefersReducedMotion,
} from "@/components/moneytrees/charts/chart-engine";

export const SOL_BOOK = generateOrderBook({ mid: 245.85, seed: 90_210, levels: 16, depth: 820 });
export const BTC_BOOK = generateOrderBook({
  mid: 96_480,
  seed: 771_204,
  levels: 16,
  tick: 12,
  depth: 26,
});

const PAD = { top: 14, right: 58, bottom: 24, left: 12 };

function compactSize(value: number) {
  return new Intl.NumberFormat("en-US", {
    notation: "compact",
    maximumFractionDigits: value >= 100 ? 1 : 2,
  }).format(value);
}

function stepPath(
  levels: BookLevel[],
  xOf: (price: number) => number,
  yOf: (total: number) => number,
  midX: number,
  baseY: number,
) {
  if (!levels.length) return "";
  let d = `M${midX.toFixed(2)},${baseY.toFixed(2)}`;
  let prevY = baseY;
  for (const level of levels) {
    const x = xOf(level.price);
    const y = yOf(level.total);
    d += `L${x.toFixed(2)},${prevY.toFixed(2)}L${x.toFixed(2)},${y.toFixed(2)}`;
    prevY = y;
  }
  const lastX = xOf(levels[levels.length - 1]!.price);
  d += `L${lastX.toFixed(2)},${baseY.toFixed(2)}Z`;
  return d;
}

export interface DepthChartProps {
  className?: string;
  book: OrderBook;
  symbol?: string;
  name?: string;
  height?: number;
  status?: ChartStatus;
  onRetry?: () => void;
}

type Layout = { w: number; h: number; x0: number; x1: number; y0: number; y1: number };

type Scale = (v: number) => number;

type Probe = { price: number; isBid: boolean; total: number };

function computeLayout(width: number, height: number): Layout {
  const w = Math.max(width, 260);
  const h = height;
  return { w, h, x0: PAD.left, x1: w - PAD.right, y0: PAD.top, y1: h - PAD.bottom };
}

function lastLevel(levels: BookLevel[]): BookLevel | undefined {
  return levels[levels.length - 1];
}

function lastTotal(levels: BookLevel[]): number {
  return lastLevel(levels)?.total ?? 0;
}

function bookDomain(book: OrderBook) {
  const lowPrice = lastLevel(book.bids)?.price ?? book.mid;
  const highPrice = lastLevel(book.asks)?.price ?? book.mid;
  const halfSpan = Math.max(book.mid - lowPrice, highPrice - book.mid) || 1;
  const maxTotal = Math.max(lastTotal(book.bids), lastTotal(book.asks), 1);
  return { domainLo: book.mid - halfSpan, domainHi: book.mid + halfSpan, maxTotal };
}

function probeAt(book: OrderBook, price: number): Probe {
  const isBid = price < book.mid;
  const side = isBid ? book.bids : book.asks;
  let level: BookLevel | null = null;
  for (const candidate of side) {
    const reached = isBid ? price <= candidate.price : price >= candidate.price;
    if (reached) level = candidate;
  }
  return { price, isBid, total: level?.total ?? 0 };
}

function sideColor(isBid: boolean) {
  return isBid ? UP : DOWN;
}

function useDepthScales(book: OrderBook, layout: Layout) {
  const { x0, x1, y0, y1 } = layout;
  const { domainLo, domainHi, maxTotal } = bookDomain(book);

  const xOf = React.useCallback(
    (price: number) => x0 + ((price - domainLo) / (domainHi - domainLo)) * (x1 - x0),
    [x0, x1, domainLo, domainHi],
  );
  const yOf = React.useCallback(
    (total: number) => y1 - (total / maxTotal) * (y1 - y0),
    [y0, y1, maxTotal],
  );
  const priceAt = React.useCallback(
    (x: number) => domainLo + ((x - x0) / (x1 - x0)) * (domainHi - domainLo),
    [x0, x1, domainLo, domainHi],
  );

  const midX = xOf(book.mid);
  const bidPath = stepPath(book.bids, xOf, yOf, midX, y1);
  const askPath = stepPath(book.asks, xOf, yOf, midX, y1);

  const priceTicks = React.useMemo(
    () => niceTicks(domainLo, domainHi, 5).filter((t) => Math.abs(xOf(t) - midX) > 26),
    [domainLo, domainHi, xOf, midX],
  );
  const sizeTicks = React.useMemo(() => niceTicks(0, maxTotal, 4), [maxTotal]);

  return { xOf, yOf, priceAt, midX, bidPath, askPath, priceTicks, sizeTicks };
}

function useDepthHover(book: OrderBook, layout: Layout, priceAt: Scale) {
  const { w, x0, x1 } = layout;
  const svgRef = React.useRef<SVGSVGElement | null>(null);
  const [hoverX, setHoverX] = React.useState<number | null>(null);

  const probe = React.useMemo(
    () => (hoverX == null ? null : probeAt(book, priceAt(hoverX))),
    [hoverX, priceAt, book],
  );

  const onMove = (clientX: number) => {
    const svg = svgRef.current;
    if (!svg) return;
    const box = svg.getBoundingClientRect();
    const x = ((clientX - box.left) / box.width) * w;
    setHoverX(Math.max(x0, Math.min(x1, x)));
  };
  const clearHover = () => setHoverX(null);

  return { svgRef, hoverX, probe, onMove, clearHover };
}

function DepthHeader({ symbol, name, book }: { symbol: string; name: string; book: OrderBook }) {
  const spreadPct = (book.spread / book.mid) * 100;
  return (
    <div className="mb-3 flex flex-wrap items-end justify-between gap-x-4 gap-y-2">
      <div>
        <div className="flex items-baseline gap-2">
          <span className="font-mono text-[12px] font-medium tracking-wide text-foreground">
            {symbol}
          </span>
          <span className="text-[12px] text-muted-foreground">{name}</span>
        </div>
        <p className="mt-1 font-mono text-[22px] font-medium leading-none tabular-nums text-foreground">
          {formatMoney(book.mid)}
        </p>
      </div>
      <dl className="flex items-end gap-4 font-mono text-[11px] tabular-nums">
        <div className="text-right">
          <dt className="text-muted-foreground/70">Spread</dt>
          <dd className="text-foreground">
            {formatSpread(book.spread, book.mid)}{" "}
            <span className="text-muted-foreground/70">({spreadPct.toFixed(3)}%)</span>
          </dd>
        </div>
        <div className="text-right">
          <dt className="text-muted-foreground/70">Bid depth</dt>
          <dd style={{ color: UP }}>{compactSize(lastTotal(book.bids))}</dd>
        </div>
        <div className="text-right">
          <dt className="text-muted-foreground/70">Ask depth</dt>
          <dd style={{ color: DOWN }}>{compactSize(lastTotal(book.asks))}</dd>
        </div>
      </dl>
    </div>
  );
}

function SizeGrid({ sizeTicks, yOf, layout }: { sizeTicks: number[]; yOf: Scale; layout: Layout }) {
  const { x0, x1 } = layout;
  return (
    <g shapeRendering="crispEdges">
      {sizeTicks.map((tick) => (
        <line
          key={tick}
          x1={x0}
          x2={x1}
          y1={yOf(tick)}
          y2={yOf(tick)}
          stroke="currentColor"
          strokeOpacity={0.12}
          strokeDasharray="2 4"
        />
      ))}
    </g>
  );
}

function MidMarker({ mid, midX, layout }: { mid: number; midX: number; layout: Layout }) {
  const { y0, y1 } = layout;
  return (
    <>
      <line
        x1={midX}
        x2={midX}
        y1={y0 - 4}
        y2={y1}
        stroke="currentColor"
        strokeOpacity={0.5}
        strokeDasharray="3 3"
      />
      <g transform={`translate(${midX}, ${y0 - 4})`}>
        <rect x={-40} y={-13} width={80} height={15} rx={4} className="fill-foreground" />
        <text
          x={0}
          y={-5}
          textAnchor="middle"
          dominantBaseline="middle"
          fontSize={9.5}
          fontWeight={600}
          className="fill-foreground font-mono tabular-nums"
        >
          MID {formatAxisPrice(mid)}
        </text>
      </g>
    </>
  );
}

function SizeAxis({ sizeTicks, yOf, layout }: { sizeTicks: number[]; yOf: Scale; layout: Layout }) {
  return (
    <g className="font-mono">
      {sizeTicks.map((tick) =>
        tick === 0 ? null : (
          <text
            key={tick}
            x={layout.x1 + 8}
            y={yOf(tick)}
            dominantBaseline="middle"
            fontSize={10.5}
            fill="currentColor"
            className="tabular-nums"
          >
            {compactSize(tick)}
          </text>
        ),
      )}
    </g>
  );
}

function PriceAxis({
  priceTicks,
  xOf,
  layout,
}: {
  priceTicks: number[];
  xOf: Scale;
  layout: Layout;
}) {
  const { x0, x1, y1 } = layout;
  return (
    <g className="font-mono">
      {priceTicks.map((tick) => (
        <text
          key={tick}
          x={Math.max(x0 + 18, Math.min(x1 - 18, xOf(tick)))}
          y={y1 + 15}
          textAnchor="middle"
          fontSize={10.5}
          fill="currentColor"
          className="tabular-nums"
        >
          {formatAxisPrice(tick)}
        </text>
      ))}
    </g>
  );
}

function DepthProbe({
  hoverX,
  probe,
  yOf,
  layout,
  reduce,
}: {
  hoverX: number | null;
  probe: Probe | null;
  yOf: Scale;
  layout: Layout;
  reduce: boolean;
}) {
  if (hoverX == null || !probe) return null;
  const { x0, x1, y0, y1 } = layout;
  const color = sideColor(probe.isBid);
  return (
    <g>
      <line
        x1={hoverX}
        x2={hoverX}
        y1={y0}
        y2={y1}
        stroke="currentColor"
        strokeOpacity={0.45}
        strokeDasharray="3 3"
        style={{ transition: reduce ? undefined : `all 90ms ${EASE}` }}
      />
      <line
        x1={x0}
        x2={x1}
        y1={yOf(probe.total)}
        y2={yOf(probe.total)}
        stroke={color}
        strokeOpacity={0.55}
        strokeDasharray="3 3"
      />
      <circle
        cx={hoverX}
        cy={yOf(probe.total)}
        r={4}
        fill={SURFACE}
        stroke={color}
        strokeWidth={2}
      />
      <g transform={`translate(${Math.max(x0 + 46, Math.min(x1 - 46, hoverX))}, ${y1 + 3})`}>
        <rect x={-46} y={0} width={92} height={16} rx={4} className="fill-foreground" />
        <text
          x={0}
          y={8.5}
          textAnchor="middle"
          dominantBaseline="middle"
          fontSize={9.5}
          fontWeight={600}
          className="fill-foreground font-mono tabular-nums"
        >
          {formatAxisPrice(probe.price)} · {compactSize(probe.total)}
        </text>
      </g>
    </g>
  );
}

export function DepthChart({
  className,
  book,
  symbol = "SOL",
  name = "Solana · USDC",
  height = 320,
  status = "ready",
  onRetry,
}: DepthChartProps) {
  const reduce = usePrefersReducedMotion();
  const [wrapRef, width] = useElementWidth<HTMLDivElement>();
  const layout = React.useMemo(() => computeLayout(width, height), [width, height]);
  const scales = useDepthScales(book, layout);
  const { xOf, yOf, midX } = scales;
  const hover = useDepthHover(book, layout, scales.priceAt);
  const uid = React.useId().replace(/:/g, "");
  const ready = width > 0;

  return (
    <div ref={wrapRef} className={cn("flex w-full flex-col text-muted-foreground/70", className)}>
      <Keyframes />

      <DepthHeader symbol={symbol} name={name} book={book} />

      <ChartState
        status={status}
        height={height}
        variant="line"
        empty={{
          title: "Empty book",
          description: "No resting orders on either side of the mid right now.",
        }}
        onRetry={onRetry}
      >
        <div className="relative w-full" style={{ height }}>
          {!ready ? null : (
            <svg
              ref={hover.svgRef}
              width={layout.w}
              height={layout.h}
              viewBox={`0 0 ${layout.w} ${layout.h}`}
              className="block w-full touch-pan-y select-none overflow-visible"
              role="img"
              aria-label={`${symbol} order book depth. Mid ${formatMoney(book.mid)}, spread ${formatSpread(book.spread, book.mid)}.`}
              tabIndex={0}
              onPointerMove={(e) => hover.onMove(e.clientX)}
              onPointerDown={(e) => hover.onMove(e.clientX)}
              onPointerLeave={hover.clearHover}
            >
              <defs>
                <linearGradient id={`${uid}-bid`} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor={UP} stopOpacity={0.4} />
                  <stop offset="100%" stopColor={UP} stopOpacity={0.04} />
                </linearGradient>
                <linearGradient id={`${uid}-ask`} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor={DOWN} stopOpacity={0.4} />
                  <stop offset="100%" stopColor={DOWN} stopOpacity={0.04} />
                </linearGradient>
              </defs>

              <SizeGrid sizeTicks={scales.sizeTicks} yOf={yOf} layout={layout} />

              <g
                style={{
                  transformBox: "fill-box",
                  transformOrigin: "bottom center",
                  animation: reduce ? undefined : `spectrum-mc-rise 620ms ${EASE} both`,
                }}
              >
                <path d={scales.bidPath} fill={`url(#${uid}-bid)`} stroke={UP} strokeWidth={1.5} />
                <path
                  d={scales.askPath}
                  fill={`url(#${uid}-ask)`}
                  stroke={DOWN}
                  strokeWidth={1.5}
                />
              </g>

              <MidMarker mid={book.mid} midX={midX} layout={layout} />

              <SizeAxis sizeTicks={scales.sizeTicks} yOf={yOf} layout={layout} />

              <PriceAxis priceTicks={scales.priceTicks} xOf={xOf} layout={layout} />

              <DepthProbe
                hoverX={hover.hoverX}
                probe={hover.probe}
                yOf={yOf}
                layout={layout}
                reduce={reduce}
              />
            </svg>
          )}
        </div>
      </ChartState>
      <ChartDataTable
        caption={`${symbol} order book depth — cumulative size by price`}
        columns={["Price", "Side", "Size", "Cumulative"]}
        rows={[
          ...book.asks.map((l) => [formatAxisPrice(l.price), "Ask", l.size, l.total]),
          ...book.bids.map((l) => [formatAxisPrice(l.price), "Bid", l.size, l.total]),
        ]}
      />
    </div>
  );
}
